import pytest
from unittest.mock import patch, MagicMock
from auth_service import SecureAuthService

class TestSecureAuthService:
    @pytest.fixture
    def auth_service(self):
        return SecureAuthService("test_secret_key")

    def test_register_user_valid_input(self, auth_service):
        result = auth_service.register_user("test@example.com", "StrongPass123")
        assert result["status"] == "success"
        assert "registered" in result["message"]

    def test_register_user_invalid_email(self, auth_service):
        result = auth_service.register_user("invalid-email", "StrongPass123")
        assert result["status"] == "error"
        assert "Invalid email" in result["message"]

    def test_register_user_weak_password(self, auth_service):
        result = auth_service.register_user("test@example.com", "weak")
        assert result["status"] == "error"
        assert "too weak" in result["message"]

    @patch('bcrypt.hashpw')
    def test_password_hashing_uses_bcrypt(self, mock_hashpw, auth_service):
        mock_hashpw.return_value = b'hashed_password'
        auth_service.register_user("test@example.com", "StrongPass123")
        mock_hashpw.assert_called_once()

    def test_rate_limiting_registration(self, auth_service):
        # Test that rate limiting blocks excessive registration attempts
        for i in range(6):  # Exceed the 5 per minute limit
            result = auth_service.register_user(f"test{i}@example.com", "StrongPass123")
        # Last request should be rate limited
        assert "rate limit" in result.get("message", "").lower()

    @patch('jwt.encode')
    def test_login_user_generates_jwt(self, mock_jwt_encode, auth_service):
        mock_jwt_encode.return_value = "test_token"
        result = auth_service.login_user("test@example.com", "StrongPass123")
        assert "token" in result
        mock_jwt_encode.assert_called_once()
